import sys
import math
from collections import deque

def euclidean_distance(x1, y1, x2, y2):
    return math.sqrt((x1 - x2) ** 2 + (y1 - y2) ** 2)

def bfs(start, grid, R, C):
    queue = deque([start])
    visited = set()
    visited.add(start)
    distances = [[float('inf')] * C for _ in range(R)]
    distances[start[0]][start[1]] = 0

    while queue:
        x, y = queue.popleft()
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < R and 0 <= ny < C and (nx, ny) not in visited:
                visited.add((nx, ny))
                distances[nx][ny] = distances[x][y] + 1
                queue.append((nx, ny))

    return distances

def count_explosions(grid, R, C):
    passengers = []
    seats = []

    for i in range(R):
        for j in range(C):
            if grid[i][j] == 'X':
                passengers.append((i, j))
            elif grid[i][j] == 'L':
                seats.append((i, j))

    explosions = 0
    for px, py in passengers:
        min_distance = float('inf')
        closest_seat = None
        for sx, sy in seats:
            dist = euclidean_distance(px, py, sx, sy)
            if dist < min_distance:
                min_distance = dist
                closest_seat = (sx, sy)

        if closest_seat:
            sx, sy = closest_seat
            if grid[sx][sy] == 'L':
                grid[sx][sy] = 'X'
            else:
                explosions += 1

    return explosions

